CREATE TABLE "Hotels" (
    "Id"           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name"         TEXT NOT NULL,
    "AddressLine1" TEXT NOT NULL,
    "City"         TEXT NOT NULL,
    "Country"      TEXT NOT NULL,
    "PostalCode"   TEXT NULL,
    "CreatedAtUtc" TIMESTAMPTZ NOT NULL,
    "UpdatedAtUtc" TIMESTAMPTZ NOT NULL
);

